p=mk("80.00"); outage_refund(p,Decimal("80.00"),T0); print("status", p.status)
# non-positive
p=mk()
try: outage_refund(p,Decimal("0"),T0)
except BillingError as e: print("zero:", e.code)
# not captured
p=Payment("p","i",Decimal("80"),status="authorized",created_at=T0)
try: outage_refund(p,Decimal("1"),T0)
except BillingError as e: print("state:", e.code)
# exceeds
p=mk("80.00")
try: outage_refund(p,Decimal("81"),T0)
except BillingError as e: print("exceeds:", e.code)
EOF"}

